def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
targets={'host':load(A/'host/latency_summary.json'),'raspberry_pi':load(A/'raspberry_pi/latency_summary.json')}
manifest=load(A/'host/workload_manifest.json');dump('workload_manifest.json',manifest)
ids={
 'original_contiguous':('cpu_contiguous_kv_fp32_v1','cpu_attention_decode_fp32','hir_cpu_attention_decode_contiguous_kv_fp32','dimension_major_strided_v_accumulation',None),
 'reordered_contiguous':('cpu_contiguous_kv_fp32_reordered_v1','cpu_attention_decode_contiguous_kv_reordered_fp32','hir_cpu_attention_decode_contiguous_kv_reordered_fp32','token_major_contiguous_v_accumulation',None),
 'token_major':('cpu_paged_kv_fp32_token_major_v1','cpu_attention_decode_paged_kv_fp32','hir_cpu_attention_decode_paged_kv_fp32','token_major_block_translation','workload'),
 'page_major':('cpu_paged_kv_fp32_page_major_v1','cpu_attention_decode_paged_kv_page_major_fp32','hir_cpu_attention_decode_paged_kv_page_major_fp32','page_major_cached_page_base','workload')}
