  for name,(cid,kid,entry,strategy,page) in ids.items():matrix.append({'target_id':target,'workload_id':m['workload_id'],'candidate_id':cid,'kernel_id':kid,'entry_point':entry,'backend':'portable_cpu','dtype':'fp32','layout':'bhcd_contiguous' if 'contiguous' in name else 'paged_phd_contiguous','implementation_strategy':strategy,'head_dimension_constraint':'static_positive','capacity_constraint':'valid_tokens_lte_capacity','workspace_bytes':t*4,'artifact_identity':'target_binary_sha256','measurement_provenance':'exact_target_workload_measured_evidence','fallback_identity':'unsupported_kv_explicit_failure' if name=='original_contiguous' else 'cpu_contiguous_kv_fp32_v1','page_tokens':pt if page else None,'request_owned_bytes':2*h*t*d*4,'internal_fragmentation_ratio':0.0})
