OBJECTIVES={'latency':(1.,0.,0.,0.),'memory_efficiency':(0.,1.,1.,.25),'balanced':(.6,.3,.1,1.)};selections=[];regrets=[];proof=[]
for target,rows in targets.items():
 for m in manifest:
  wid=m['workload_id'];rs=[r for r in rows if r['workload_id']==wid];by={r['candidate']:r for r in rs};mem=2*m['heads']*m['valid_tokens']*m['head_dim']*4;minimum=min(r['native_append_decode']['p95_ms'] for r in rs)
  for objective,(lw,mw,fw,constraint) in OBJECTIVES.items():
   eligible=[r for r in rs if objective!='memory_efficiency' or r['native_append_decode']['p95_ms']<=minimum*(1+constraint)]
